WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_a554c093a351569f>
    <urn:graphragprov:unit:u_cbed32ecb9ba3756>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
